var rocks=UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None);var renderers=rocks.SelectMany(r=>r.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.name=="Embedded Minerals").ToArray();float originalTime=Time.timeScale;Time.timeScale=0;EditorApplication.isPaused=true;int stage=0,frame=Time.frameCount;var report=new System.Collections.Generic.List<string>();EditorApplication.CallbackFunction tick=null;
